#include "main.h"
#include <stdint.h>

/* Generated by CubeMX in Core/Src/main.c. */
void SystemClock_Config(void);

int main(void)
{
    HAL_Init();
    SystemClock_Config();

    if (BSP_LED_Init(LED_GREEN) != BSP_ERROR_NONE ||
        BSP_PB_Init(BUTTON_USER, BUTTON_MODE_GPIO) != BSP_ERROR_NONE) {
        Error_Handler();
    }

    const uint32_t slow_interval_ms = 500U;
    const uint32_t fast_interval_ms = 100U;
    uint32_t blink_interval_ms = slow_interval_ms;
    uint32_t last_led_toggle = HAL_GetTick();
    uint32_t candidate_since = HAL_GetTick();
    uint8_t candidate_pressed = 0U;
    uint8_t button_pressed = 0U;

    while (1) {
        const uint32_t now = HAL_GetTick();
        const uint8_t raw_pressed =
            (BSP_PB_GetState(BUTTON_USER) == GPIO_PIN_SET) ? 1U : 0U;

        /* Accept a button change only after it stays steady for 30 ms. */
        if (raw_pressed != candidate_pressed) {
            candidate_pressed = raw_pressed;
            candidate_since = now;
        }

        if ((candidate_pressed != button_pressed) &&
            ((now - candidate_since) >= 30U)) {
            button_pressed = candidate_pressed;
            if (button_pressed != 0U) {
                blink_interval_ms =
                    (blink_interval_ms == slow_interval_ms)
                        ? fast_interval_ms
                        : slow_interval_ms;
            }
        }

        if ((now - last_led_toggle) >= blink_interval_ms) {
            (void)BSP_LED_Toggle(LED_GREEN);
            last_led_toggle = now;
        }

        HAL_Delay(1U);
    }
}
